er":2,"km":115.1,"name":"Cusco highland rise","category":"Cat 2","length_km":8.6,"avg_gradient":5,"points_scheme":[10,6,4,2,1],"time_bonus_seconds":[]}]},{"id":"da199e4d-b880-4a9e-9aeb-695655430417","n":7,"name":"Stage 7 · Cusco Highlands Finale","start":"Cusco","finish":"Cusco","route":"Cusco → Oropesa → highland loop → Cusco","distance":111.9,"terrain":"mountain","profile":"climber","gain":2420,"flat":12,"hilly":54,"mountain":34,"eligible":false,"slot":null,"finish_type":"uphill_finish","elev":[3399,3250,3380,3650,3550,3440,3399],"format":"road_race","profile_points":[{"km":0,"elevation":3399,"elevation_m":3399},{"km":19,"elevation":3250,"elevation_m":3250},{"km":36.9,"elevation":3380,"elevation_m":3380},{"km":56,"elevation":3650,"elevation_m":3650},{"km":75,"elevation":3550,"elevation_m":3550},{"km":92.9,"elevation":3440,"elevation_m":3440},{"km":111.9,"elevation":3399,"elevation_m":3399}],"sprints":[{"number":1,"km":40.3,"name":"Cusco route sprint","points":"standard","points_scheme":[12,8,5,3,1],"time_bonus_seconds":[3,2,1]},{"number":2,"km":81.7,"name":"Cusco approach sprint","points":"standard","points_scheme":[10,6,4,2,1],"time_bonus_seconds":[3,2,1]}],"climbs":[{"number":1,"km":47,"name":"Cusco route climb","category":"Cat 3","length_km":6.4,"avg_gradient":4.6,"points_scheme":[5,3,2,1],"time_bonus_seconds":[]},{"number":2,"km":85,"name":"Cusco highland rise","category":"Cat 2","length_km":8.6,"avg_gradient":5,"points_scheme":[10,6,4,2,1],"time_bonus_seconds":[]}]}]},{"race_id":"b8ad02ec-3f40-4b0a-a9ca-2b71429d0501","pool_id":"482fd4f7-ec82-4efd-9b96-c783d84e9501","cc":"CG","name":"Grand Prix de Brazzaville","short":"GP Brazzaville","host":"Brazzaville","category":"1.2","prize":39000,"stages":[{"id":"b8ad02ec-3f40-4b0a-a9ca-2b71429d0511","n":1,"name":"Grand Prix de Brazzaville","start":"Brazzaville","finish":"Brazzaville","route":"Brazzaville → Kinkala corridor on RN1 → southern return circuit → Brazzaville","distance":152.3,"terrain":"hilly","profile":"all_